Sound pickup=Tone(.22f,720,.55f),step=Tone(.08f,78,.42f),heartbeat=Tone(.18f,52,.65f),attack=Tone(.7f,31,.95f),creak=Tone(.95f,118,.35f),sting=Tone(.45f,185,.65f),hum=Tone(1.1f,43,.30f),door=Tone(.8f,65,.70f);
