std::vector<Fuse>fu={{{-14.8f,.95f,11.7f}},{{14.8f,.95f,11.5f}},{{-14.5f,.95f,-11}}};std::vector<Hide>hide={{{-18,1,12.9f},1.35f},{{18,1,12.9f},1.35f},{{-18,1,-11},1.35f},{{18,1,-11},1.35f}};
Camera3D cam{};cam.position={0,1.62f,14.4f};cam.up={0,1,0};cam.fovy=70;cam.projection=CAMERA_PERSPECTIVE;Vector3 enemy={0,1,3.5f},face={0,0,1},target={0,1,11},lastSeen=enemy,noise={};AI ai=AI::PATROL;int pi=0,searchStep=0,got=0;float yaw=0,pitch=0,stam=100,batt=100,stateT=0,attackT=0,pstep=0,estep=0,noiseT=0,humT=2,scareT=0;bool hiding=false,dead=false,won=false,menu=true,paused=false,doorOpen=false,flash=true;
while(!WindowShouldClose()){float dt=std::min(GetFrameTime(),.05f);if(IsKeyPressed(KEY_F11))ToggleFullscreen();if(menu){BeginDrawing();ClearBackground({7,8,10,255});DrawText("NIGHT HOUSE",415,130,64,RAYWHITE);DrawText("ENTER  PLAY",535,320,27,RAYWHITE);DrawText("WASD move   SHIFT sprint   E hide / interact   F flashlight   ESC pause",265,395,17,{150,150,150,255});EndDrawing();if(IsKeyPressed(KEY_ENTER))menu=false;continue;}if(IsKeyPressed(KEY_ESCAPE)){paused=!paused;if(paused)EnableCursor();else DisableCursor();}if(paused){BeginDrawing();ClearBackground({7,8,10,245});DrawText("PAUSED",520,245,52,RAYWHITE);EndDrawing();continue;}if(dead||won){BeginDrawing();ClearBackground(dead?Color{23,3,6,255}:Color{5,25,10,255});DrawText(dead?"SHE CAUGHT YOU":"YOU ESCAPED",dead?390:430,225,60,RAYWHITE);DrawText("ENTER restart",530,400,21,RAYWHITE);EndDrawing();if(IsKeyPressed(KEY_ENTER)){cam.position={0,1.62f,14.4f};enemy={0,1,3.5f};face={0,0,1};got=0;dead=won=hiding=doorOpen=false;ai=AI::PATROL;for(auto&f:fu)f.got=false;}continue;}
Vector2 md=GetMouseDelta();yaw-=md.x*.00235f;pitch=Clamp(pitch-md.y*.0020f,-1.18f,1.18f);Vector3 fwd={std::sin(yaw),0,std::cos(yaw)},right={-std::cos(yaw),0,std::sin(yaw)};cam.target=Vector3Add(cam.position,{std::sin(yaw)*std::cos(pitch),std::sin(pitch),std::cos(yaw)*std::cos(pitch)});
bool nh=false;for(const auto&h:hide)if(D(cam.position,h.p)<h.r)nh=true;if(IsKeyPressed(KEY_E)&&nh)hiding=!hiding;bool moving=IsKeyDown(KEY_W)||IsKeyDown(KEY_A)||IsKeyDown(KEY_S)||IsKeyDown(KEY_D);bool sprint=IsKeyDown(KEY_LEFT_SHIFT)&&moving&&stam>1&&!hiding;float sp=sprint?4.f:2.35f;Vector3 mv{};if(IsKeyDown(KEY_W))mv=Vector3Add(mv,fwd);if(IsKeyDown(KEY_S))mv=Vector3Subtract(mv,fwd);if(IsKeyDown(KEY_A))mv=Vector3Add(mv,right);if(IsKeyDown(KEY_D))mv=Vector3Subtract(mv,right);if(Vector3Length(mv)>.01f&&!hiding){Move(cam.position,Vector3Scale(Vector3Normalize(mv),sp*dt),.34f,w);stam=sprint?std::max(0.f,stam-dt*30.f):stam;}else if(!sprint)stam=std::min(100.f,stam+dt*23.f);if(IsKeyPressed(KEY_F)&&batt>1)flash=!flash;if(flash)batt=std::max(0.f,batt-dt*.42f);
pstep-=dt;if(moving&&!hiding&&pstep<=0){pstep=sprint?.23f:.42f;SetSoundVolume(step,sprint?.42f:.25f);PlaySound(step);if(sprint){noise=cam.position;noiseT=1.0f;}}
for(auto&x:fu)if(!x.got&&D(cam.position,x.p)<1.1f&&IsKeyPressed(KEY_E)){x.got=true;got++;SetSoundVolume(pickup,.52f);PlaySound(pickup);noise=cam.position;noiseT=1.6f;}if(got==3&&!doorOpen&&cam.position.z<-15.2f&&std::abs(cam.position.x)<3&&IsKeyPressed(KEY_E)){doorOpen=true;Hear(door,{0,1,-17},cam.position,right,1.2f);won=true;}noiseT=std::max(0.f,noiseT-dt);
float ed=D(enemy,cam.position);Vector3 to=Vector3Subtract({cam.position.x,1.55f,cam.position.z},{enemy.x,1.35f,enemy.z});if(Vector3Length(to)>.01f)to=Vector3Normalize(to);bool sight=!hiding&&ed<16.5f&&Vector3DotProduct(to,face)>.22f&&LOS({enemy.x,1.3f,enemy.z},cam.position,w);bool hear=noiseT>0&&D(enemy,noise)<(sprint?15.f:9.5f);
if(sight){lastSeen=cam.position;ai=AI::CHASE;stateT=0;scareT=std::max(scareT,1.8f);}else if(hear&&ai!=AI::WINDUP){target=noise;ai=AI::INVESTIGATE;stateT=0;}
stateT+=dt;scareT-=dt;
if(ai==AI::CHASE){target=cam.position;face=to;if(!sight){if(D(enemy,lastSeen)<.8f){ai=AI::SEARCH;stateT=0;searchStep=0;}else if(stateT>3.2f){ai=AI::SEARCH;stateT=0;searchStep=0;}}if(ed<1.65f&&attackT<=0&&!hiding){ai=AI::WINDUP;attackT=.55f;}}
if(ai==AI::WINDUP){face=to;attackT-=dt;if(attackT<=0){if(D(enemy,cam.position)<1.8f&&!hiding){Hear(attack,enemy,cam.position,right,1.3f);dead=true;}else{ai=AI::SEARCH;stateT=0;searchStep=0;}}}
else if(ai==AI::SEARCH){static const Vector3 off[6]={{2,1,0},{-2,1,0},{0,1,2},{0,1,-2},{3,1,3},{-3,1,-3}};if(searchStep<6){target=Vector3Add(lastSeen,off[searchStep]);if(D(enemy,target)<.75f)searchStep++;}else if(stateT>5.f){ai=AI::PATROL;stateT=0;}face=Vector3Normalize(Vector3Subtract(target,enemy));Move(enemy,Vector3Scale(face,1.45f*dt),.43f,w);}
else if(ai==AI::INVESTIGATE){face=Vector3Normalize(Vector3Subtract(target,enemy));if(D(enemy,target)<.75f){ai=AI::SEARCH;lastSeen=target;stateT=0;searchStep=0;}else Move(enemy,Vector3Scale(face,2.0f*dt),.43f,w);}
else if(ai==AI::PATROL){if(D(enemy,target)<.8f){pi=(pi+1)%6;target=Vector3{{0,1,11},{-15,1,11},{15,1,2},{0,1,-4},{0,1,-12},{0,1,5}}[pi];}face=Vector3Normalize(Vector3Subtract(target,enemy));Move(enemy,Vector3Scale(face,1.05f*dt),.43f,w);}
if(ai==AI::CHASE){face=to;Move(enemy,Vector3Scale(face,4.05f*dt),.43f,w);} 
estep-=dt;if(estep<=0&&(ai==AI::CHASE||ai==AI::INVESTIGATE||ai==AI::PATROL)){estep=ai==AI::CHASE?.28f:.45f;Hear(step,enemy,cam.position,right,ai==AI::CHASE?1.15f:.72f);}if(ed<6&&!hiding&&GetRandomValue(0,38)==0)Hear(heartbeat,enemy,cam.position,right,Clamp(1-ed/7.f,0.f,1.f));humT-=dt;if(humT<=0){humT=GetRandomValue(7,11);Hear(hum,{0,1,0},cam.position,right,.75f);}if(GetRandomValue(0,260)==0)Hear(creak,{(float)GetRandomValue(-18,18),1,(float)GetRandomValue(-14,14)},cam.position,right,.65f);
BeginDrawing();ClearBackground({4,5,7,255});BeginMode3D(cam);DrawPlane({0,0,0},{42,34},{38,35,31,255});DrawCube({0,3.1f,0},42,.12f,34,{24,24,23,255});for(const auto&x:w){Box(wall,x.p,x.s,Color{195,184,165,255});DrawCubeWires(x.p,x.s.x,x.s.y,x.s.z,{25,22,20,255});}Furniture(wood,metal,fabric);for(const auto&h:hide)Closet(wood,h.p);if(!doorOpen){Box(wood,{-12,1.6f,-17},{18,3.2f,.7f});Box(wood,{12,1.6f,-17},{18,3.2f,.7f});}for(const auto&x:fu)if(!x.got){DrawCylinder(x.p,.16f,.16f,.42f,12,{214,206,174,255});DrawSphere({x.p.x,x.p.y+.22f,x.p.z},.13f,{235,220,110,255});}Enemy(enemy,face,(float)GetTime(),ai==AI::CHASE||got==3);EndMode3D();DrawRectangle(0,0,GetScreenWidth(),GetScreenHeight(),flash?Color{0,0,0,18}:Color{0,0,0,112});DrawRectangle(0,0,GetScreenWidth(),85,{0,0,0,185});DrawText(TextFormat("FUSES  %d / 3",got),30,20,25,RAYWHITE);DrawText(ai==AI::CHASE?"SHE SEES YOU":ai==AI::INVESTIGATE?"SHE HEARD THAT":ai==AI::SEARCH?"SHE IS SEARCHING":"",500,20,20,{205,165,165,255});DrawText("WASD move   SHIFT sprint   E hide / interact   F flashlight   ESC pause",30,53,16,{155,155,155,255});DrawRectangle(1035,22,190,11,{28,28,28,255});DrawRectangle(1035,22,(int)(190*stam/100.f),11,{190,190,190,255});DrawText("STAMINA",1035,38,11,{150,150,150,255});DrawRectangle(1035,59,190,8,{28,28,28,255});DrawRectangle(1035,59,(int)(190*batt/100.f),8,{150,150,140,255});if(nh)DrawText(hiding?"E leave hiding":"E hide",535,620,19,RAYWHITE);DrawText(got<3?"Find the three fuses.":"All fuses found. Reach the front door.",390,655,19,{190,190,190,255});Crosshair();EndDrawing();}
